  "commands.catalog.docs.open.title": "Open Herald Docs",
  "commands.catalog.docs.open.description": "Open Herald Docs, or open a document in it (.docx, .md or .txt) so the person sees it. The answer gives its outline, and lists anything Herald shows differently from the file.",
  "commands.catalog.docs.open.arg.path": "A Word document, Markdown or text file (full path or ~/…)",
  "commands.catalog.docs.new.title": "Start a new document",
  "commands.catalog.docs.new.description": "Start a new document in Herald Docs and show it: blank, from a template (Herald Docs’ own, with its page, styles, headers and footers and sample text to replace, or one the person saved: docs.listTemplates), or with content (Markdown: headings, lists, tables, pictures from files), which with a template takes the place of its sample text. With path it is saved there at once (never over a file that exists). Draft from a brief by writing the content yourself.",
  "commands.catalog.docs.new.arg.name": "The tab’s name, and the file name it is offered when saved",
  "commands.catalog.docs.new.arg.content": "What it starts with, in Markdown",
  "commands.catalog.docs.new.arg.template": "A template’s id or name: blank, letter, cover-letter, cv, report, memo, meeting-notes, essay, project-proposal, newsletter, invoice, thank-you-note, recipe, or one the person saved",
  "commands.catalog.docs.new.arg.size": "The paper: a4, letter, legal or a5 (the locale’s when left out)",
  "commands.catalog.docs.new.arg.path": "Save it here at once: a new .docx, .md or .txt file (full path or ~/…)",
  "commands.catalog.docs.list.title": "What is open in Herald Docs",
  "commands.catalog.docs.list.description": "The documents open in Herald Docs (name, path, unsaved edits), which one is in front, and the text selected in each.",
  "commands.catalog.docs.read.title": "Read a document",
  "commands.catalog.docs.read.description": "Read a document: its outline (headings), word count, page, and content as Markdown (the default) or plain text, the whole of it or one heading’s section; part=selection gives just the selected and marked text of an open document; part=comments, notes, headers (headers and footers, {page} and {pages} where those fields are), sections or tocs (tables of contents) gives those, and the answer to any other part says which of them the document has. Long documents come back cut at maxChars: read them by section.",
  "commands.catalog.docs.read.arg.document": "The document: a file (full path or ~/…) or the name of an open document as its tab shows it; the one in front in Herald Docs when left out",
  "commands.catalog.docs.read.arg.part": "markdown (the default), text, outline, selection, comments, notes, headers, sections or tocs",
