  "commands.catalog.docs.read.arg.maxChars": "At most this many characters of content (20000)",
  "commands.catalog.docs.find.title": "Find in a document",
  "commands.catalog.docs.find.description": "Find text in a document: how many times it appears, and each place with the words around it and the heading it is under.",
  "commands.catalog.docs.find.arg.document": "The document: a file (full path or ~/…) or the name of an open document as its tab shows it; the one in front in Herald Docs when left out",
