  "commands.catalog.docs.write.title": "Write in a document",
  "commands.catalog.docs.write.description": "Put content in a document as one step to undo: Markdown by default (headings, bold and italic, lists, task lists, tables, links, quotes, code, pictures from files as ![alt](~/path.png)), at the end, the start, the selection, the marked text, under the marked text’s paragraph (or the selection’s when nothing is marked), or in a heading’s section (append, prepend or replace). One paragraph at the selection joins its line of text.",
  "commands.catalog.docs.write.arg.document": "The document: a file (full path or ~/…) or the name of an open document as its tab shows it; the one in front in Herald Docs when left out",
  "commands.catalog.docs.write.arg.content": "What to write, in Markdown (or plain text with format=text)",
  "commands.catalog.docs.write.arg.format": "markdown (the default) or text",
  "commands.catalog.docs.write.arg.at": "Where: end (the default), start, selection (in place of what is selected, or at the caret), marked (in place of the text Herald marked for this request), after (under the paragraph the marked text is in, or the selection when nothing is marked) or heading",
  "commands.catalog.docs.write.arg.heading": "A heading (its text, or its number in the outline from 1): the content goes in its section",
  "commands.catalog.docs.write.arg.mode": "With heading: append (at the end of the section, the default), prepend (right under the heading) or replace (in place of the section, keeping the heading)",
  "commands.catalog.docs.replace.title": "Find and replace in a document",
  "commands.catalog.docs.replace.description": "Replace text in a document as one step to undo: every match (the default) or the first; each replacement keeps the formatting where its match starts. An empty replacement deletes the matches.",
