  "commands.catalog.docs.removeToc.arg.toc": "Which table of contents, from 1 in the order they come (the only one when left out)",
  "commands.catalog.docs.listTemplates.title": "List Herald Docs’ templates",
  "commands.catalog.docs.listTemplates.description": "The templates a new document can start from (docs.new template=): Herald Docs’ own, each with its id, name and what it holds, and those the person saved, with their id, name and when.",
  "commands.catalog.docs.statistics.title": "A document’s statistics",
  "commands.catalog.docs.statistics.description": "A document’s statistics: words, characters with and without spaces, paragraphs, sentences, words per sentence, reading and speaking time, reading ease (Flesch, from 0 to 100, with what it means) and the US school grade (Flesch-Kincaid), and its pages when it is open. They count the body, not notes, comments, headers or footers; heading gives one section’s, selection=true the selection’s.",
