  "ui.d054612714c2": "Content-Aware Fill",
  "ui.35f1d6e9ec7d": "Fills the selection with pixels from around it. It all happens on this computer.",
  "ui.049c1389d6f6": "Put the fill",
  "ui.2db9f09204e4": "Copy from",
  "ui.2786545e6f0a": "Sample all layers (the fill goes on a new layer) ",
  "ui.c0cc58cd4d37": "Fill ",
  "ui.2ca4fd3abcab": "Generative Fill",
  "ui.417febb014bb": "New Generated Layer",
  "ui.1aaf53ef4129": "What goes in the selection",
  "ui.ef66729cd3d5": "What the new layer shows",
  "ui.d016c6304072": "What goes here? Leave it empty to carry on what is around it.",
  "ui.8111af318de8": "Describe the picture, e.g. “a paper lantern glowing orange”",
  "ui.b789345de36e": "Hermes makes it with its image generation tool and places it as a new layer",
  "ui.99fbe8540432": ", masked to the selection",
  "ui.dfe88b5c770f": ". A picture of ",
  "ui.046af5886e8b": "the area",
  "ui.f5c0a269ef61": "nothing from the image",
  "ui.9b49a8c71047": " is saved for it in /tmp. Some image services charge for each picture. ",
  "ui.941321b593e5": "Ask Hermes to edit the image",
  "ui.7a01591d11c0": "Ask Hermes to edit… (make it moodier, put the logo bottom right)",
